    "theme": "Les lois de la chasteté et de la calomnie, l'innocence disculpée par la révélation, les règles de la pudeur et de l'entrée dans les demeures, et le grand verset de la Lumière",
    "note_pedagogique": "La sourate de la vie communautaire pure : elle légifère sur la calomnie (après l'affaire de l'ifk, l'accusation portée contre ʿĀʾisha), pose les règles du regard et du vêtement, et culmine au verset 35, le plus célèbre sur la nature divine : « Allah est la Lumière des cieux et de la terre », déployé dans l'image de la niche, de la lampe et de l'olivier béni.",
