      "ar": "لَّوْلَا جَاءُو عَلَيْهِ بِأَرْبَعَةِ شُهَدَاءَ فَإِذْ لَمْ يَأْتُواْ بِالشُّهَدَاءِ فَأُوْلَـٰئِكَ عِندَ اللَّهِ هُمُ الْكَٰذِبُونَ",
      "translit": "Lawlā jāʾū ʿalayhi biʾarbaʿati shuhadāʾa faʾidh lam yaʾtū bish-shuhadāʾi faʾūlāʾika ʿinda llāhi humu l-kādhibūn",
